function hexToRgb(h){ h=String(h).replace('#',''); if(h.length===3) h=h.split('').map(function(c){return c+c;}).join(''); return [parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)]; }
function rgbToHex(r,g,b){ var t=function(v){var n=Math.max(0,Math.min(255,Math.round(v)));return ('0'+n.toString(16)).slice(-2);}; return '#'+t(r)+t(g)+t(b); }
function lerpHex(a,b,t){ t=Math.max(0,Math.min(1,t)); var A=hexToRgb(a),B=hexToRgb(b); return rgbToHex(A[0]+(B[0]-A[0])*t, A[1]+(B[1]-A[1])*t, A[2]+(B[2]-A[2])*t); }
function gradientStops(a,b,n){ n=n||5; var out=[]; for(var i=0;i<n;i++) out.push(lerpHex(a,b,n===1?0:i/(n-1))); return out; }
var EXPORTS={hexToRgb:hexToRgb, rgbToHex:rgbToHex, lerpHex:lerpHex, gradientStops:gradientStops};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GradientTextForgePure = EXPORTS; }
